export const RETAIL_RATES_BY_KEY: Record<string, RetailRateItem> = Object.fromEntries(
  RETAIL_RATES.map((r) => [r.key, r])
);

export function retailRate(key: string): RetailRateItem | undefined {
  return RETAIL_RATES_BY_KEY[key];
}
